class LocaleDataHandle {
    long facet_counter; // Simple state copy

public:
    LocaleDataHandle() : facet_counter(0) {}

    // Copy constructor required to be noexcept
    // if used in standard library contexts (like std::locale).
    LocaleDataHandle(const LocaleDataHandle& other) noexcept
        : facet_counter(other.facet_counter)
    {
        // Optimization: Compiler omits stack unwinding code.
        // If an exception occurs, std::terminate() is called.
    }
};

// Runtime check for guarantee:
static_assert(noexcept(LocaleDataHandle(
    std::declval<const LocaleDataHandle&>())), 
    "Copy must be non-throwing");
